using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.USR.RazasMascota;namespace GraphApi.Services.USR.RazasMascota{    public class RazasMascotaService : IRazasMascotaService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public RazasMascotaService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadRazasMascota>> GetRazasMascotas(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM usr.RazasMascota (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadRazasMascota>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetRazasMascotasDynamic(            int? razaMascotaID,            int? tipoMascotaID,            string? razaMascota,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "RazaMascotaID, TipoMascotaID, RazaMascota, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM usr.RazasMascota (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (razaMascotaID.HasValue)            {                vSql.Append(" AND RazaMascotaID = @RazaMascotaID");                vParameters.Add("RazaMascotaID",razaMascotaID);            }            if (!string.IsNullOrWhiteSpace(razaMascota))            {                vSql.Append(" AND RazaMascota LIKE @RazaMascota");                vParameters.Add("RazaMascota",$"%{razaMascota}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadRazasMascota> CreateRazasMascota(clCreateRazasMascota objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO usr.RazasMascota                (TipoMascotaID, RazaMascota, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@TipoMascotaID, @RazaMascota, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.TipoMascotaID,                objInput.RazaMascota,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT RazaMascotaID, TipoMascotaID, RazaMascota, bEliminado                FROM usr.RazasMascota (NOLOCK)                WHERE RazaMascotaID = @RazaMascotaID;";            var vReadParams = new { RazaMascotaID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadRazasMascota>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el RazasMascota con ID {vNewId}.");            return vCreated;        }        public async Task<clReadRazasMascota?> UpdateRazasMascota(clUpdateRazasMascota objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("RazaMascotaID", objInput.RazaMascotaID);            if (objInput.TipoMascotaID != null)            {                vSets.Add("TipoMascotaID = @TipoMascotaID");                vParameters.Add("TipoMascotaID", objInput.TipoMascotaID);            }            if (objInput.RazaMascota is not null)            {                vSets.Add("RazaMascota = @RazaMascota");                vParameters.Add("RazaMascota", objInput.RazaMascota);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE usr.RazasMascota                SET {vSetClause}                WHERE RazaMascotaID = @RazaMascotaID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT RazaMascotaID, TipoMascotaID, RazaMascota, bEliminado                FROM usr.RazasMascota (NOLOCK)                WHERE RazaMascotaID = @RazaMascotaID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadRazasMascota>(sSelect, new {  objInput.RazaMascotaID });        }        public async Task<bool> DeleteRazasMascota(int nRazasMascotaID)        {            const string sSql = @"                DELETE FROM usr.RazasMascota                WHERE RazaMascotaID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nRazasMascotaID });            return vAffected > 0;        }    }}